-- The shared library's EU notes for the UK, the US and Brazil, checked 12 November 2026 (Brazil: EU adequacy, Implementing Decision (EU) 2026/179).
UPDATE "country_risk" SET "eu_adequacy" = 'adequate', "eu_adequacy_note" = 'EU adequacy decision for the UK, renewed by Implementing Decision (EU) 2025/2574 of 19 December 2025, in force until 27 December 2031. Checked 12 November 2026.', "sources" = '[{"title":"Commission Implementing Decision (EU) 2025/2574 (UK adequacy, renewed)","url":"https://eur-lex.europa.eu/eli/dec_impl/2025/2574/oj","published":"2025-12-19"}]'::jsonb, "updated_at" = now() WHERE "code" = 'GB' AND "organisation_id" IS NULL;--> statement-breakpoint
UPDATE "country_risk" SET "eu_adequacy" = 'partial', "eu_adequacy_note" = 'Only for recipients certified under the EU-US Data Privacy Framework (Implementing Decision (EU) 2023/1795, in force). The General Court upheld it in Latombe (T-553/23, 3 September 2025); the appeal, C-703/25 P, is pending. After Trump v. Slaughter (US Supreme Court, 29 June 2026) the EDPB asked the Commission to assess its effect on the decision. Check certification per recipient, and keep an Article 46 fallback in the contract. Checked 12 November 2026.', "sources" = '[{"title":"CJEU C-311/18 (Schrems II) on s.702 FISA and EO 12333","published":"2020-07-16"},{"title":"UK Extension to the EU-US Data Privacy Framework"},{"title":"Commission Implementing Decision (EU) 2023/1795 (EU-US Data Privacy Framework)","url":"https://eur-lex.europa.eu/eli/dec_impl/2023/1795/oj","published":"2023-07-10"},{"title":"General Court, T-553/23 Latombe v Commission (appeal C-703/25 P pending)","published":"2025-09-03"}]'::jsonb, "updated_at" = now() WHERE "code" = 'US' AND "organisation_id" IS NULL;--> statement-breakpoint
UPDATE "country_risk" SET "eu_adequacy" = 'adequate', "eu_adequacy_note" = 'EU adequacy decision for Brazil, Implementing Decision (EU) 2026/179 of 26 January 2026. No UK approval regulations for Brazil. Checked 12 November 2026.', "sources" = '[{"title":"Commission Implementing Decision (EU) 2026/179 (Brazil adequacy)","url":"https://eur-lex.europa.eu/eli/dec_impl/2026/179/oj","published":"2026-01-26"}]'::jsonb, "updated_at" = now() WHERE "code" = 'BR' AND "organisation_id" IS NULL;
